INSERT OVERWRITE lr_serverless_aws_us_catalog.bricksurance_content.document (document_id, document_type_code, title, product_id, policy_id, claim_id, submission_id, extracted_text, volume_path, created_date, source_system_code) VALUES
  ('doc_0001', 'POLICY_WORDING', 'Commercial Property Standard — Policy Wording v1', 'prd_0001', NULL, NULL, NULL, 'Commercial Property Standard POLICY WORDING. Section A - Insuring clause: the insurer agrees to indemnify the insured for buildings, contents, business interruption as specified in the schedule, subject to the limits and deductibles stated. Section B - Exclusions: this policy does not cover loss arising from flood in coastal postcode districts; nor liability assumed under contract beyond that implied by law; nor loss caused by wilful misconduct of the insured. Section C - Conditions: claims must be notified without undue delay; the insured must take reasonable precautions; cover is subject to the sanctions limitation clause. Section D - Claims: first notification through any channel including the digital FNOL service; the insurer may appoint a loss adjuster above the delegated settlement limit.', NULL, DATE '2026-01-01', 'PAS_CORE'),
  ('doc_0002', 'POLICY_WORDING', 'Motor Fleet — Policy Wording v1', 'prd_0002', NULL, NULL, NULL, 'Motor Fleet POLICY WORDING. Section A - Insuring clause: the insurer agrees to indemnify the insured for motor own damage, motor tpl as specified in the schedule, subject to the limits and deductibles stated. Section B - Exclusions: this policy does not cover loss arising from use for racing, pace-making or speed testing; nor liability assumed under contract beyond that implied by law; nor loss caused by wilful misconduct of the insured. Section C - Conditions: claims must be notified without undue delay; the insured must take reasonable precautions; cover is subject to the sanctions limitation clause. Section D - Claims: first notification through any channel including the digital FNOL service; the insurer may appoint a loss adjuster above the delegated settlement limit.', NULL, DATE '2026-01-01', 'PAS_CORE'),
  ('doc_0003', 'POLICY_WORDING', 'SME Combined Liability — Policy Wording v1', 'prd_0003', NULL, NULL, NULL, 'SME Combined Liability POLICY WORDING. Section A - Insuring clause: the insurer agrees to indemnify the insured for public liability as specified in the schedule, subject to the limits and deductibles stated. Section B - Exclusions: this policy does not cover loss arising from asbestos-related injury or damage; nor liability assumed under contract beyond that implied by law; nor loss caused by wilful misconduct of the insured. Section C - Conditions: claims must be notified without undue delay; the insured must take reasonable precautions; cover is subject to the sanctions limitation clause. Section D - Claims: first notification through any channel including the digital FNOL service; the insurer may appoint a loss adjuster above the delegated settlement limit.', NULL, DATE '2026-01-01', 'PAS_CORE'),
  ('doc_0004', 'POLICY_WORDING', 'Marine Cargo — Policy Wording v1', 'prd_0004', NULL, NULL, NULL, 'Marine Cargo POLICY WORDING. Section A - Insuring clause: the insurer agrees to indemnify the insured for cargo as specified in the schedule, subject to the limits and deductibles stated. Section B - Exclusions: this policy does not cover loss arising from war, strikes and confiscation except as endorsed; nor liability assumed under contract beyond that implied by law; nor loss caused by wilful misconduct of the insured. Section C - Conditions: claims must be notified without undue delay; the insured must take reasonable precautions; cover is subject to the sanctions limitation clause. Section D - Claims: first notification through any channel including the digital FNOL service; the insurer may appoint a loss adjuster above the delegated settlement limit.', NULL, DATE '2026-01-01', 'PAS_CORE'),
  ('doc_0005', 'CLAIM_EVIDENCE', 'Fire investigation summary — CLM-2026-000001', NULL, NULL, 'clm_0001', NULL, 'FIRE INVESTIGATION SUMMARY. Site: warehouse and distribution centre, Manchester M3 5EN. Origin: electrical fault in first-floor conveyor control cabinet. Sprinkler activation contained spread; smoke damage across two floors of racked stock. No indicators of deliberate ignition. Recommended reserve basis: reinstatement of control systems, stock write-off on floors one and two, business interruption per schedule.', NULL, DATE '2026-03-25', 'CLM_CORE'),
  ('doc_0006', 'MRC_SLIP', 'MRC slip — property catastrophe XoL 2026', NULL, NULL, NULL, 'sub_0002', 'MARKET REFORM CONTRACT. Type: Property Catastrophe Excess of Loss. Reinsured: Bricksurance SE. Period: 12 months at 1 January 2026. Layer 1: GBP 10,000,000 excess of GBP 5,000,000 each and every loss occurrence; one reinstatement at 100% additional premium. Layer 2: GBP 20,000,000 excess of GBP 15,000,000; one reinstatement. Territorial scope: United Kingdom. Exclusions: war, cyber as per LMA5564, contingent business interruption without named suppliers.', NULL, DATE '2025-11-15', 'RI_CORE');

